def is_prime(n):
    # Check if n is less than 2
    if n < 2:
        return False

    # Loop from 2 to the square root of n
    for i in range(2, int(n**0.5) + 1):
        # Check if n is divisible by any number in this range
        if n % i == 0:
            return False

    # If no divisor was found, n is prime
    return True

